function uploadField(label,image){return `<label class="file-button full">↑ ${label}<input name="image" type="file" accept="image/png,image/jpeg,image/webp,image/gif"></label><img class="image-preview" ${image?`src="${esc(image)}"`:'hidden'} alt="Image preview"><label class="check-label"><input name="removeImage" type="checkbox"> Remove uploaded image</label>`;}
function missionFields(x,id){return `${questScheduleFields(x)}<section class="editor-section"><div class="panel-title"><h3>XP parameters</h3><label class="switch-label"><input type="checkbox" name="xpEnabled" ${x.xpEnabled?'checked':''}> Earn XP</label></div><div id="rating-fields" class="range-fields">${rating('friction','Friction',x.friction,null,5)}${rating('resistance','Resistance',x.resistance,resistanceLabels,5)}${rating('slipRate','Slip Rate',x.slipRate,slipLabels,4)}${rating('drain','Drain',x.drain,drainLabels,4)}</div><div class="xp-preview"><span>MISSION PAYOUT</span><b id="xp-preview">${xpFor(x)} XP</b></div><p class="fine-print">Drain has the largest XP effect (+0 / 24 / 56 / 96). Friction and Resistance add up to 48 each; Slip Rate adds up to 48.</p></section><div class="form-grid"><div class="currency-editor">${field('Base credits / side quests pay 50%','coins',x.coinMode==='manual'?x.coins:defaultCoins(x),'number','min="0" max="1000000" step="1" required')}<input type="hidden" name="coinMode" value="${x.coinMode}"><b id="credit-payout">${coinsFor(x)} CR FINAL</b><small id="credit-mode">${x.coinMode==='auto'?'XP DEFAULT / 1 CR PER 5 XP':'MANUAL OVERRIDE'}</small><button type="button" class="secondary full" data-reset-coins>Reset to XP default</button></div></div>${questCalendarFields(x)}${select('Parent mission','parent',[['','Standalone'],...state.missions.filter(m=>m.id!==id&&m.status==='active'&&!descendant(m.id,id)).map(m=>[m.id,m.title])],x.parent||'')}<fieldset><legend>Linked skills</legend>${state.skills.flatMap(parent=>parent.parentId?[]:[parent,...state.skills.filter(c=>c.parentId===parent.id)]).map(s=>`<label class="skill-check"><input type="checkbox" name="skills" value="${s.id}" ${x.skills.includes(s.id)?'checked':''}><span class="inline-icon">${iconSvg(s.icon)||esc(s.icon)}</span> ${s.parentId?'↳ ':''}${esc(s.title)}${s.parentId?' / 45%':''}</label>`).join('')}</fieldset><label class="field">Subtasks <small>One per line. Existing steps can be checked below.</small><textarea name="steps" rows="3">${esc(x.subtasks.map(t=>t.title).join('\n'))}</textarea></label>${x.subtasks.map((t,i)=>`<label class="check-label"><input type="checkbox" name="stepdone" value="${i}" ${t.done?'checked':''}>${esc(t.title)}</label>`).join('')}${field('Location','location',x.location||'','text','maxlength="300"')}`;}
function colorControl(name,label,value){return `<label>${esc(label)}<input name="${name}" type="color" value="${value}"></label>`;}
function paletteFields(c){const outfit=outfitPalette(c),item=itemPalette(c);return `<section class="editor-section"><h3>Outfit parts / ${esc(clothesNames[c.clothes])}</h3><div class="color-grid part-colors">${outfitParts[c.clothes].map(p=>colorControl(`cloth:${c.clothes}:${p.key}`,p.label,outfit[p.key])).join('')}</div></section><section class="editor-section"><h3>Equipment parts / ${esc(itemNames[c.accessory])}</h3>${itemParts[c.accessory].length?`<div class="color-grid part-colors">${itemParts[c.accessory].map(p=>colorControl(`gear:${c.accessory}:${p.key}`,p.label,item[p.key])).join('')}</div>`:'<p class="muted">Select equipment to edit its colors.</p>'}</section>`;}
function profileFields(){const c=characterDraft;return `<div id="character-preview" class="editor-character">${characterView(c)}</div>${field('Handle','name',state.profile.name,'text','required maxlength="60"')}${field('Designation','title',state.profile.title,'text','maxlength="100"')}${select('Display mode','characterMode',[['pixel','Pixel operator'],['image','Custom image / animated GIF']],c.mode)}<section class="editor-section"><h3>Body & hair</h3>${select('Hairstyle','hair',hairNames.map((n,i)=>[i,n]),c.hair)}<div class="color-grid">${colorControl('skin','Skin',c.skin)}${colorControl('hairColor','Hair',c.hairColor)}</div></section><section class="editor-section eye-category"><h3>Eyes</h3>${select('Eye shape','eyeStyle',eyeNames.map((n,i)=>[i,n]),c.eyeStyle)}<div class="color-grid">${colorControl('eyes','Iris',c.eyes)}${colorControl('eyeWhite','White / highlight',c.eyeWhite)}${colorControl('pupilColor','Pupil',c.pupilColor)}</div></section><div class="form-grid">${select('Clothing','clothes',clothesNames.map((n,i)=>[i,n]),c.clothes)}${select('Item','accessory',itemNames.map((n,i)=>[i,n]),c.accessory)}</div><div id="palette-fields">${paletteFields(c)}</div><label class="field">Character size ratio <output id="character-scale-value">${c.scale}%</output><input type="range" name="scale" min="60" max="160" step="5" value="${c.scale}"></label>${uploadField('Upload operator image / GIF',state.profile.avatar)}<p class="fine-print">24 × 32 pixel operator. Each clothing style and item remembers its own palette. Animated GIF uploads retain animation (1.5 MB maximum).</p>`;}
function characterFromForm(){const f=Object.fromEntries(new FormData($('#item-form'))),c=structuredClone(characterDraft);Object.assign(c,{hair:+f.hair,accessory:+f.accessory,clothes:+f.clothes,scale:+f.scale,skin:f.skin,hairColor:f.hairColor,eyes:f.eyes,eyeStyle:+f.eyeStyle,eyeWhite:f.eyeWhite,pupilColor:f.pupilColor,mode:f.characterMode});for(const [name,value] of Object.entries(f)){const match=/^(cloth|gear):(\d+):([a-z]+)$/.exec(name);if(!match)continue;const map=match[1]==='cloth'?c.outfitColors:c.itemColors;map[match[2]]??={};map[match[2]][match[3]]=value;}return c;}
function updateCharacterPreview(){characterDraft=characterFromForm();$('#character-preview').innerHTML=characterView(characterDraft,editingImage);$('#character-scale-value').value=characterDraft.scale+'%';}
function bindCharacter(){$$('#item-form select,#item-form input[type=color],#item-form input[type=range]').forEach(input=>input.oninput=()=>{updateCharacterPreview();if(['clothes','accessory'].includes(input.name)){$('#palette-fields').innerHTML=paletteFields(characterDraft);bindCharacter();}});}
function openSkillRadar(){const modal=$('#editor');modal.classList.add('radar-dialog');const main=state.skills.filter(s=>!s.parentId),all=main.flatMap(p=>[p,...state.skills.filter(s=>s.parentId===p.id)]);modal.innerHTML=`<div class="modal-heading"><div><span class="eyebrow">// OPERATOR STATS</span><h2>Full skill web</h2></div><button type="button" class="close" data-close aria-label="Close">×</button></div><p class="muted">All main skills and subskills. Every point uses the same XP scale.</p><div class="radar-full-chart">${radarSvg(all,true)}</div><div class="radar-full-legend">${all.map((s,i)=>`<div><span>${String(i+1).padStart(2,'0')}</span><b>${s.parentId?'↳ ':''}${esc(s.title)}${s.parentId?`<small>${esc(main.find(p=>p.id===s.parentId)?.title||'')}</small>`:''}</b><span>${s.xp} XP</span></div>`).join('')}</div>`;modal.querySelector('[data-close]').onclick=()=>modal.close();modal.showModal();}

async function readImage(file,preserveGif=false){if(!file)throw Error('Select an image.');if(!['image/png','image/jpeg','image/webp','image/gif'].includes(file.type))throw Error('Use PNG, JPG, WebP, or GIF.');if(file.size>10*1024*1024)throw Error('Image limit: 10 MB.');if(preserveGif&&file.type==='image/gif'){if(file.size>1500000)throw Error('Animated GIF limit: 1.5 MB.');return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Could not read GIF.'));r.readAsDataURL(file);});}return new Promise((resolve,reject)=>{const r=new FileReader();r.onerror=()=>reject(Error('Could not read image.'));r.onload=()=>{const img=new Image();img.onerror=()=>reject(Error('Invalid image.'));img.onload=()=>{const c=document.createElement('canvas'),ratio=Math.min(1,1200/Math.max(img.width,img.height));c.width=Math.max(1,Math.round(img.width*ratio));c.height=Math.max(1,Math.round(img.height*ratio));c.getContext('2d').drawImage(img,0,0,c.width,c.height);resolve(c.toDataURL('image/webp',.8));};img.src=r.result;};r.readAsDataURL(file);});}
function download(content,name){if(native){window.DaemonNative.exportBackup(content,name);return;}const url=URL.createObjectURL(new Blob([content],{type:name.endsWith('.ics')?'text/calendar':'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function importBackup(e){try{const file=e.target.files[0];if(!file)return;if(file.size>25*1024*1024)throw Error('Backup limit: 25 MB.');const incoming=validate(JSON.parse(await file.text()));if(dirty&&!confirm('Discard unsaved appearance settings before import?'))return;if(!confirm('Replace local data with this backup? Export your current data first to keep it.'))return;if(mutate(()=>state=incoming)){dirty=false;draft=structuredClone(state.settings.appearance);render();toast('BACKUP RESTORED');}}catch(e){toast(e.message);}}
async function action(a){if(a==='new-mission')return chooseQuest();if(a==='calendar-new'){{const selected=new Date(localDay(calendarDate)+'T12:00:00');newQuestDate=(localDay(selected)===today()&&selected<=new Date()?new Date(Date.now()+3600000):selected).toISOString();}return chooseQuest(true);}if(a.startsWith('new-')){newSkillParent='';return openEditor(a.slice(4));}if(a==='profile')return openEditor('profile');if(a==='radar')return openSkillRadar();if(a==='refresh-permissions'){render();syncAlarms();}if(a==='test-alarm')window.DaemonNative.testAlarm();if(a==='save-appearance'){saveAppearance();render();}if(a==='discard-appearance'){draft=structuredClone(state.settings.appearance);dirty=false;render();}if(a==='clear-cover'){mutate(()=>state.settings.cover='');render();}if(a==='export')download(JSON.stringify(state,null,2),`daemon-deck-${today()}.json`);if(a==='export-raw')download(localStorage.getItem('daemon-deck')||'{}','daemon-deck-original.json');if(a==='web-notifications'){if(!('Notification'in window)){toast('Notifications unavailable in this browser.');return;}const result=await Notification.requestPermission();$('#web-permission').textContent=result;if(result==='denied')toast('Notifications blocked. Change this site’s browser permissions to enable.');}}
window.daemonRefreshPermissions=()=>{render();syncAlarms();};
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='Save these settings';}});
// Browser notifications are session-only. Persist delivered IDs to avoid duplicates on reload.
let lastWebCheck=Date.now();setInterval(()=>{if(native)return;const now=Date.now();const events=alarmPlan(state,lastWebCheck-1).filter(a=>a.at<=now);if('Notification'in window&&Notification.permission==='granted'){let fired;try{fired=JSON.parse(localStorage.getItem('daemon-web-fired')||'[]');}catch{fired=[];}for(const event of events){const key=event.id+':'+event.at;if(fired.includes(key))continue;try{new Notification(event.title,{body:event.body,icon:'icon.svg',tag:event.id});fired.push(key);}catch{}}try{localStorage.setItem('daemon-web-fired',JSON.stringify(fired.slice(-1000)));}catch{}}lastWebCheck=now;},15000);
setInterval(()=>{if($('#vitals'))$('#vitals').outerHTML=vitalsPanel();},60000);
render();syncAlarms();if('serviceWorker'in navigator&&!native)navigator.serviceWorker.register('./sw.js').catch(()=>{});

function iconPicker(value){return `<details class="icon-library"><summary>Choose icon / 50 symbols</summary><div class="icon-picker">${icons.map(i=>`<button type="button" data-pick-icon="${i.id}" class="${value===i.id?'selected':''}" aria-label="${i.label} icon" aria-pressed="${value===i.id}">${iconSvg(i.id)}<small>${i.label}</small></button>`).join('')}</div></details>`;}
function chooseQuest(fromCalendar=false){if(!fromCalendar)newQuestDate='';const modal=$('#editor');modal.classList.remove('radar-dialog');modal.innerHTML=`<div class="modal-heading"><div><span class="eyebrow">// NEW QUEST</span><h2>Select quest type</h2></div><button type="button" class="close" data-close aria-label="Close">×</button></div><div class="quest-type-grid"><button type="button" class="quest-type" data-kind="main"><span>⚑</span><b>Mission</b><small>Full XP · full credits<br>Scheduled deadline and recurrence</small></button><button type="button" class="quest-type side" data-kind="side"><span>◇</span><b>Side Quest</b><small>Full XP · 50% credits<br>Optional unlimited Repeatable mode</small></button></div>`;modal.querySelector('[data-close]').onclick=()=>modal.close();modal.querySelectorAll('[data-kind]').forEach(b=>b.onclick=()=>{newQuestKind=b.dataset.kind;openEditor('mission');if(fromCalendar){$('[name=calEnabled]').checked=true;updateQuestVisibility();}});if(!modal.open)modal.showModal();}
function questScheduleFields(x){const r=recurrenceFor(x),dayNames=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];return `<div class="quest-type-banner ${x.kind}">${x.kind==='side'?'◇ SIDE QUEST / 50% CREDITS · 100% XP':'⚑ MAIN MISSION / FULL PAYOUT'}</div>${x.kind==='side'?`<label class="setting"><span>Repeatable <small>Unlimited uses. No deadline. Stays on the board until deleted.</small></span><input type="checkbox" name="repeatable" ${x.repeatable?'checked':''}></label>`:''}<section class="editor-section"><h3>Schedule & recurrence</h3><div data-deadline-fields><p class="muted">Created ${esc(fmt(x.createdAt))}. Pre-reminders divide creation → due time.</p><div class="form-grid">${field('Due date & time','dueAt',localDateTime(x.dueAt||new Date(Date.now()+86400000)),'datetime-local','required')}${select('Pre-reminders','reminderCount',Array.from({length:6},(_,i)=>[i,String(i)]),x.reminderCount)}${select('Reminder timing','reminderMode',[['even','Evenly spaced'],['manual','Custom times']],x.reminderMode)}</div><div id="reminder-timeline">${reminderTimes(x).map((v,i)=>`<label class="reminder-slot"><span>0${i+1}</span><input type="datetime-local" name="reminderAt" value="${localDateTime(v)}" ${x.reminderMode==='even'?'readonly':'required'} aria-label="Pre-reminder ${i+1}"></label>`).join('')}<div class="due-slot"><b>◉ DUE</b><span>${x.dueAt?esc(fmt(x.dueAt)):'No deadline'}</span></div></div><p class="fine-print">${native?'Android stores deadline alarms while the app is closed.':'Web alerts require an open tab; Android provides background alarms.'}</p>${select('Repeat schedule','repeat',[['none','No repeat'],['daily','Daily'],['weekly','Weekly'],['biweekly','Biweekly / every 2 weeks'],['monthly','Monthly']],x.repeat)}<div data-repeat-details><div class="form-grid">${field('Interval multiplier','repeatInterval',r.interval,'number','min="1" max="365" required')}<p class="muted">Daily: every N days. Weekly: every N weeks. Biweekly: every 2 × N weeks. Monthly: every N months.</p></div><fieldset data-weekly><legend>Repeat on</legend>${dayNames.map((d,i)=>`<label class="skill-check"><input type="checkbox" name="repeatDays" value="${i}" ${r.weekdays.includes(i)?'checked':''}>${d}</label>`).join('')}</fieldset><div data-monthly>${select('Monthly pattern','monthlyMode',[['date','Day of month'],['weekday','Ordinal weekday']],r.monthlyMode)}<div class="form-grid"><div data-month-date>${field('Day of month','monthDay',r.monthDay,'number','min="1" max="31" required')}${select('Short months','missingDay',[['last','Use last day'],['skip','Skip that month']],r.missingDay)}</div><div data-month-week>${select('Which week','weekOrdinal',[[1,'First'],[2,'Second'],[3,'Third'],[4,'Fourth'],[5,'Fifth'],[-1,'Last']],r.weekOrdinal)}${select('Weekday','repeatWeekday',dayNames.map((d,i)=>[i,d]),r.weekday)}</div></div></div>${select('End recurrence','repeatEnd',[['never','Never'],['until','On a date'],['count','After N occurrences']],r.end)}<div data-end-until>${field('Last recurrence date','repeatUntil',r.until||localDay(new Date(Date.now()+365*86400000)),'date','required')}</div><div data-end-count>${field('Total occurrences (including first)','repeatCount',r.count,'number','min="1" max="10000" required')}</div><p class="fine-print">Completing a scheduled quest creates its next future occurrence. Missed dates are skipped; the end date/count still applies. Local clock time is preserved across daylight saving changes. Week-based schedules start Monday.</p></div></div>${field('Estimated minutes','duration',x.duration,'number','required min="1" max="100000"')}</section>`;}
function questCalendarFields(x){const c=x.calendar;return `<section class="editor-section"><label class="setting"><span>Add to Calendar <small>Only opted-in quests appear in Calendar.</small></span><input type="checkbox" name="calEnabled" ${c.enabled?'checked':''}></label><div data-calendar-fields><div class="quest-type-banner ${x.kind}">PRIMARY TAG: ${x.kind==='side'?'SIDE QUEST':'MAIN'}</div><div class="form-grid">${field('Event duration / minutes','calDuration',c.duration,'number','min="1" max="10080" required')}<label class="field">Event color<input type="color" name="calColor" value="${c.color}"></label></div><label class="check-label"><input type="checkbox" name="calAllDay" ${c.allDay?'checked':''}> All-day event</label><label class="check-label"><input type="checkbox" name="calBusy" ${c.busy?'checked':''}> Mark as busy</label>${field('Additional tags / comma separated','calTags',c.tags.join(', '),'text','maxlength="1200"')}<label class="field">Calendar notes<textarea name="calNotes" maxlength="20000" rows="4">${esc(c.notes)}</textarea></label><p class="fine-print">The event starts at the quest deadline; duration controls its end time. Recurring dates project automatically. Calendar notes are separate from private quest notes. Exported calendar files include these notes and tags.</p></div><p data-repeatable-calendar class="fine-print">Repeatable side quests have no date. Turn Repeatable off to add this quest to Calendar.</p></section>`;}
function setGroup(selector,show){const group=$('#editor '+selector);if(!group)return;group.hidden=!show;group.querySelectorAll('input,select,textarea').forEach(i=>i.disabled=!show);}
function updateQuestVisibility(){const infinite=!!$('[name=repeatable]')?.checked,freq=$('[name=repeat]')?.value||'none';setGroup('[data-deadline-fields]',!infinite);setGroup('[data-repeat-details]',!infinite&&freq!=='none');setGroup('[data-weekly]',!infinite&&['weekly','biweekly'].includes(freq));setGroup('[data-monthly]',!infinite&&freq==='monthly');const monthly=$('[name=monthlyMode]')?.value;setGroup('[data-month-date]',!infinite&&freq==='monthly'&&monthly==='date');setGroup('[data-month-week]',!infinite&&freq==='monthly'&&monthly==='weekday');setGroup('[data-end-until]',!infinite&&freq!=='none'&&$('[name=repeatEnd]').value==='until');setGroup('[data-end-count]',!infinite&&freq!=='none'&&$('[name=repeatEnd]').value==='count');const cal=$('[name=calEnabled]');if(cal){cal.disabled=infinite;if(infinite)cal.checked=false;setGroup('[data-calendar-fields]',!infinite&&cal.checked);$('[data-repeatable-calendar]').hidden=!infinite;}}
function bindQuestSchedule(x){for(const name of ['repeatable','repeat','monthlyMode','repeatEnd','calEnabled'])if($(`[name=${name}]`))$(`[name=${name}]`).addEventListener('change',updateQuestVisibility);updateQuestVisibility();}
function recurrenceFromForm(f){if(f.has('repeatable'))return defaultRecurrence();const get=n=>f.get(n),due=get('dueAt'),base=defaultRecurrence(due);return {...base,frequency:get('repeat')||'none',interval:+(get('repeatInterval')||1),weekdays:['weekly','biweekly'].includes(get('repeat'))?f.getAll('repeatDays').map(Number):base.weekdays,monthlyMode:get('monthlyMode')||'date',monthDay:+(get('monthDay')||base.monthDay),weekOrdinal:+(get('weekOrdinal')||base.weekOrdinal),weekday:+(get('repeatWeekday')??base.weekday),missingDay:get('missingDay')||'last',end:get('repeatEnd')||'never',until:get('repeatUntil')||'',count:+(get('repeatCount')||10)};}
function calendarFromForm(f,x){return {...x.calendar,enabled:f.has('calEnabled')&&!f.has('repeatable'),duration:+(f.get('calDuration')||x.calendar.duration),color:f.get('calColor')||x.calendar.color,allDay:f.has('calAllDay'),busy:f.has('calBusy'),tags:f.has('calEnabled')?String(f.get('calTags')||'').split(',').map(t=>t.trim()).filter(Boolean):x.calendar.tags,notes:f.get('calNotes')??x.calendar.notes};}
function confirmCompletion(id){const m=state.missions.find(m=>m.id===id);if(!m||m.status!=='active')return;if(m.subtasks.some(t=>!t.done)||state.missions.some(c=>c.parent===id&&c.status==='active')){toast('Finish pending subtasks and child missions.');openEditor('mission',id);return;}const modal=$('#editor');modal.classList.remove('radar-dialog');modal.innerHTML=`<div class="modal-heading"><div><span class="eyebrow">// CONFIRM EXECUTION</span><h2>Complete ${m.kind==='side'?'side quest':'mission'}?</h2></div><button class="close" data-close aria-label="Close">×</button></div><h3>${esc(m.title)}</h3><div class="completion-payout"><span>+${xpFor(m)} XP</span><span>+${coinsFor(m)} CR</span></div><p class="muted">${m.repeatable?'This repeatable side quest stays active. Subtasks reset for the next use.':m.repeat!=='none'?'The next scheduled occurrence will be created if its end rule allows.':'This quest will move to Cleared.'}</p><div class="modal-actions"><button class="secondary" data-close>Cancel</button><button class="primary" id="confirm-complete">Confirm completion</button></div>`;modal.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>modal.close());$('#confirm-complete').onclick=()=>{$('#confirm-complete').disabled=true;unlockAudio().catch(()=>{});const before=level(state.profile.xp),xp=xpFor(m),credits=coinsFor(m);if(mutate(()=>complete(state,id))){modal.close();render();toast(`QUEST CLEARED / +${xp} XP / +${credits} CR${level(state.profile.xp)>before?' / LEVEL UP':''}`);rewardSounds(state.settings.sounds,{xp,credits,leveled:level(state.profile.xp)>before}).catch(()=>toast('Sound playback unavailable. Check sound settings.'));}else $('#confirm-complete').disabled=false;};if(!modal.open)modal.showModal();}
function soundSettings(){const s=state.settings.sounds;return `<section class="panel sound-settings"><div class="panel-title"><h2>Sound deck</h2><label class="check-label"><input type="checkbox" id="sound-muted" ${s.muted?'checked':''}> Mute rewards</label></div><label class="field">Volume <output id="sound-volume-value">${s.volume}%</output><input type="range" id="sound-volume" min="0" max="100" value="${s.volume}"></label><p class="fine-print">Four original sounds per category. “Wasteland terminal” is an original retro sci-fi level-up cue. Local clips: up to 12 seconds / 550 KB each. Changes save immediately.</p><div class="sound-grid">${soundCategories.map(([id,title])=>`<section><h3>${title}</h3><select data-sound-select="${id}" aria-label="${title} sound">${soundNames[id].map((label,i)=>`<option value="${i}" ${s[id].mode==='preset'&&s[id].preset===i?'selected':''}>${label}</option>`).join('')}<option value="custom" ${s[id].mode==='custom'?'selected':''} ${!s[id].data?'disabled':''}>Local audio${s[id].name?' / '+esc(s[id].name):''}</option></select><div class="sound-actions"><button class="secondary" data-sound-preview="${id}">Preview</button><label class="file-button">Upload audio<input type="file" data-sound-upload="${id}" accept="audio/mpeg,audio/wav,audio/ogg,audio/mp4,audio/aac,audio/webm"></label></div>${s[id].data?`<button class="text-button" data-sound-clear="${id}">Remove local clip</button>`:''}</section>`).join('')}</div></section>`;}
function bindSounds(){if($('#sound-muted'))$('#sound-muted').onchange=e=>mutate(()=>state.settings.sounds.muted=e.target.checked);if($('#sound-volume'))$('#sound-volume').oninput=e=>{mutate(()=>state.settings.sounds.volume=+e.target.value);$('#sound-volume-value').value=e.target.value+'%';};$$('[data-sound-select]').forEach(input=>input.onchange=()=>{mutate(()=>{const a=state.settings.sounds[input.dataset.soundSelect];a.mode=input.value==='custom'?'custom':'preset';if(a.mode==='preset')a.preset=+input.value;});});$$('[data-sound-preview]').forEach(b=>b.onclick=()=>previewSound(b.dataset.soundPreview,state.settings.sounds).catch(()=>toast('This audio could not be played.')));$$('[data-sound-upload]').forEach(input=>input.onchange=async()=>{try{const data=await readAudio(input.files[0]);if(mutate(()=>Object.assign(state.settings.sounds[input.dataset.soundUpload],data,{mode:'custom'})))render();}catch(e){toast(e.message);}});$$('[data-sound-clear]').forEach(b=>b.onclick=()=>{mutate(()=>Object.assign(state.settings.sounds[b.dataset.soundClear],{data:'',name:'',mode:'preset'}));render();});}
function updateClock(){$$('.cyber-clock').forEach(el=>{const d=new Date();el.innerHTML=`<b>${d.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',hour12:false})}</b><small>${d.toLocaleDateString([],{month:'short',day:'2-digit',year:'numeric'})}</small>`;el.dateTime=d.toISOString();});}
setInterval(updateClock,1000);
function calendarRange(){const d=new Date(calendarDate);d.setHours(0,0,0,0);if(calendarView==='day')return [d,new Date(d.getFullYear(),d.getMonth(),d.getDate()+1)];if(calendarView==='week'){d.setDate(d.getDate()-(d.getDay()+6)%7);return [d,new Date(d.getFullYear(),d.getMonth(),d.getDate()+7)];}const start=new Date(d.getFullYear(),d.getMonth(),1);if(calendarView==='month'){start.setDate(start.getDate()-(start.getDay()+6)%7);return [start,new Date(start.getFullYear(),start.getMonth(),start.getDate()+42)];}return [start,new Date(d.getFullYear(),d.getMonth()+1,1)];}
function eventStart(e){return e.quest.calendar.allDay?new Date(localDay(e.at)+'T00:00:00'):new Date(e.at);}
function eventEnd(e){const start=eventStart(e);return e.quest.calendar.allDay?new Date(start.getFullYear(),start.getMonth(),start.getDate()+1):new Date(+start+e.quest.calendar.duration*60000);}
function onDay(e,date){const start=new Date(localDay(date)+'T00:00:00'),end=new Date(start.getFullYear(),start.getMonth(),start.getDate()+1);return eventStart(e)<end&&eventEnd(e)>start;}
function calendarPage(){const [from,to]=calendarRange(),tags=[...new Set(state.missions.filter(m=>m.calendar.enabled).flatMap(m=>m.calendar.tags))];calendarEntries=calendarEvents(state.missions,new Date(+from-8*86400000),to).filter(e=>(calendarKind==='all'||e.quest.kind===calendarKind)&&(calendarTag==='all'||e.quest.calendar.tags.includes(calendarTag))&&(calendarShowCompleted||e.projected||e.quest.status!=='completed')&&`${e.quest.title} ${e.quest.calendar.notes} ${e.quest.calendar.tags.join(' ')}`.toLowerCase().includes(calendarQuery.toLowerCase())&&eventEnd(e)>from);return heading('// LOCAL CALENDAR','Calendar','Opted-in missions and side quests. Stored on this device.','<button class="primary" data-action="calendar-new">＋ Add quest</button>')+`<div class="calendar-toolbar"><div class="calendar-nav"><button class="secondary" data-calendar-step="-1" aria-label="Previous period">←</button><button class="secondary" data-calendar-today>Today</button><button class="secondary" data-calendar-step="1" aria-label="Next period">→</button></div><label class="calendar-date"><span class="sr-only">Calendar date</span><input type="date" id="calendar-date" value="${localDay(calendarDate)}"></label><div class="calendar-views">${['month','week','day','agenda'].map(view=>`<button class="${view===calendarView?'selected':''}" data-calendar-view="${view}">${view[0].toUpperCase()+view.slice(1)}</button>`).join('')}</div></div><h2 class="calendar-period">${calendarDate.toLocaleDateString([],{month:'long',year:'numeric'})}${calendarView==='week'?` / ${from.toLocaleDateString()}–${new Date(+to-1).toLocaleDateString()}`:''}</h2><div class="calendar-filters"><div class="calendar-kind">${[['all','All'],['main','Main'],['side','Side Quest']].map(([id,label])=>`<button data-calendar-kind="${id}" class="${calendarKind===id?'selected':''}">${label}</button>`).join('')}</div><label class="search">⌕ <input id="calendar-search" value="${esc(calendarQuery)}" placeholder="Search events / notes / tags" aria-label="Search calendar"></label><select id="calendar-tag" aria-label="Calendar tag"><option value="all">All additional tags</option>${tags.map(t=>`<option ${t===calendarTag?'selected':''}>${esc(t)}</option>`).join('')}</select><label class="check-label"><input id="calendar-completed" type="checkbox" ${calendarShowCompleted?'checked':''}> Show cleared</label></div>${calendarView==='month'?monthCalendar(from):calendarView==='week'?weekCalendar(from):calendarView==='day'?dayCalendar(from):agendaCalendar(from,to)}<div class="calendar-io panel"><h3>Calendar files</h3><p class="muted">Export opted-in quests as iCalendar (.ics) for other calendar apps, or Daemon Calendar JSON for exact quest settings. Imports are previewed, merged and deduplicated by event identity. Import never awards XP or credits.</p><div class="calendar-io-actions"><button class="secondary" data-calendar-export="ics">↓ Export .ics</button><button class="secondary" data-calendar-export="json">↓ Export JSON</button><label class="file-button">↑ Import calendar<input id="calendar-import" type="file" accept=".ics,.json,text/calendar,application/json"></label></div></div>`;}
function eventButton(e,compact=false){const m=e.quest;return `<button class="calendar-event ${m.kind} ${m.status==='completed'&&!e.projected?'cleared':''}" style="--event-color:${m.calendar.color}" data-calendar-event="${esc(e.key)}"><span class="event-type">${m.kind==='side'?'◇ SIDE QUEST':'⚑ MAIN'}${e.projected?' / ↻':m.status==='completed'?' / ✓':''}</span><b>${esc(m.title)}</b><small>${m.calendar.allDay?'ALL DAY':new Date(e.at).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}${!compact?' / '+m.calendar.duration+' min':''}</small>${!compact&&m.calendar.notes?`<p>${esc(m.calendar.notes.slice(0,200))}</p>`:''}${!compact&&m.calendar.tags.length?`<span class="event-tags">${m.calendar.tags.map(esc).join(' · ')}</span>`:''}</button>`;}
function monthCalendar(start){return `<div class="month-calendar"><div class="calendar-weekdays">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<span>${d}</span>`).join('')}</div><div class="calendar-grid">${Array.from({length:42},(_,i)=>{const d=new Date(start.getFullYear(),start.getMonth(),start.getDate()+i),events=calendarEntries.filter(e=>onDay(e,d));return `<section class="calendar-cell ${d.getMonth()!==calendarDate.getMonth()?'other-month':''} ${localDay(d)===today()?'is-today':''}"><button class="calendar-cell-date" data-calendar-day="${localDay(d)}" aria-label="Open ${d.toLocaleDateString()}">${d.getDate()}<small>${events.length?' / '+events.length:''}</small></button><div class="calendar-cell-events">${events.slice(0,3).map(e=>eventButton(e,true)).join('')}${events.length>3?`<button class="text-button" data-calendar-day="${localDay(d)}">+${events.length-3} more</button>`:''}</div></section>`;}).join('')}</div></div><p class="fine-print">Tap a date to open its full day. ↻ marks a projected recurring occurrence.</p>`;}
function weekCalendar(start){return `<div class="week-calendar" tabindex="0" aria-label="Week calendar, scroll horizontally"><div class="week-columns">${Array.from({length:7},(_,i)=>{const d=new Date(start.getFullYear(),start.getMonth(),start.getDate()+i),events=calendarEntries.filter(e=>onDay(e,d));return `<section><button class="week-date ${localDay(d)===today()?'is-today':''}" data-calendar-day="${localDay(d)}">${d.toLocaleDateString([],{weekday:'short',day:'numeric'})}</button>${events.length?events.map(e=>eventButton(e)).join(''):'<p class="muted">No events</p>'}</section>`;}).join('')}</div></div>`;}
function dayCalendar(date){const events=calendarEntries.filter(e=>onDay(e,date)),allDay=events.filter(e=>e.quest.calendar.allDay),timed=events.filter(e=>!e.quest.calendar.allDay).sort((a,b)=>eventStart(a)-eventStart(b)),base=new Date(localDay(date)+'T00:00:00'),ends=[],placed=[];for(const event of timed){const start=eventStart(event),end=eventEnd(event),s=start<base?0:start.getHours()*60+start.getMinutes(),t=localDay(end)!==localDay(base)?1440:end.getHours()*60+end.getMinutes();let lane=ends.findIndex(v=>v<=s);if(lane<0)lane=ends.length;ends[lane]=t;placed.push({event,start:s,end:Math.max(s+1,t),lane});}const lanes=Math.max(1,ends.length);return `<div class="day-calendar"><h3>${date.toLocaleDateString([],{weekday:'long',month:'long',day:'numeric'})}</h3>${allDay.length?`<div class="all-day-events"><span class="eyebrow">ALL DAY</span>${allDay.map(e=>eventButton(e)).join('')}</div>`:''}<div class="day-timeline"><div class="day-hour-grid">${Array.from({length:24},(_,hour)=>`<div><span>${String(hour).padStart(2,'0')}:00</span></div>`).join('')}</div><div class="day-time-events">${placed.map(({event,start,end,lane})=>`<div class="timed-event-slot" style="top:${start}px;height:${Math.max(32,end-start)}px;left:${lane/lanes*100}%;width:${100/lanes}%">${eventButton(event,true)}</div>`).join('')}</div></div></div>`;}

function agendaCalendar(from,to){const days=[];for(const d=new Date(from);d<to;d.setDate(d.getDate()+1)){const items=calendarEntries.filter(e=>onDay(e,d));if(items.length)days.push(`<section class="agenda-day"><h3>${d.toLocaleDateString([],{weekday:'short',month:'short',day:'numeric'})}</h3>${items.map(e=>eventButton(e)).join('')}</section>`);}return days.length?`<div class="calendar-agenda">${days.join('')}</div>`:'<div class="empty"><span>▦</span><h3>No events match this view</h3><p>Enable Add to Calendar inside a quest, or import a calendar file.</p></div>';}
function bindCalendar(){$$('[data-calendar-view]').forEach(b=>b.onclick=()=>{calendarView=b.dataset.calendarView;render();});$$('[data-calendar-step]').forEach(b=>b.onclick=()=>{const n=+b.dataset.calendarStep;if(['month','agenda'].includes(calendarView)){calendarDate=new Date(calendarDate.getFullYear(),calendarDate.getMonth()+n,1);}else calendarDate.setDate(calendarDate.getDate()+n*(calendarView==='week'?7:1));render();});$$('[data-calendar-today]').forEach(b=>b.onclick=()=>{calendarDate=new Date();render();});if($('#calendar-date'))$('#calendar-date').onchange=e=>{if(e.target.value){calendarDate=new Date(e.target.value+'T12:00:00');render();}};$$('[data-calendar-day]').forEach(b=>b.onclick=()=>{calendarDate=new Date(b.dataset.calendarDay+'T12:00:00');calendarView='day';render();});$$('[data-calendar-kind]').forEach(b=>b.onclick=()=>{calendarKind=b.dataset.calendarKind;render();});if($('#calendar-tag'))$('#calendar-tag').onchange=e=>{calendarTag=e.target.value;render();};if($('#calendar-completed'))$('#calendar-completed').onchange=e=>{calendarShowCompleted=e.target.checked;render();};if($('#calendar-search'))$('#calendar-search').oninput=e=>{calendarQuery=e.target.value;const at=e.target.selectionStart;render();$('#calendar-search').focus();$('#calendar-search').setSelectionRange(at,at);};$$('[data-calendar-event]').forEach(b=>b.onclick=()=>calendarDetails(b.dataset.calendarEvent));$$('[data-calendar-export]').forEach(b=>b.onclick=()=>{const quests=state.missions.filter(m=>m.calendar.enabled&&!m.repeatable),format=b.dataset.calendarExport;download(format==='ics'?exportICS(quests):JSON.stringify({format:'daemon-calendar',version:1,quests},null,2),`daemon-calendar-${today()}.${format}`);});if($('#calendar-import'))$('#calendar-import').onchange=importCalendarFile;}
function calendarDetails(key){const event=calendarEntries.find(e=>e.key===key);if(!event)return;const m=event.quest,modal=$('#editor');modal.classList.remove('radar-dialog');modal.innerHTML=`<div class="modal-heading"><div><span class="eyebrow">${m.kind==='side'?'SIDE QUEST':'MAIN'} / ${event.projected?'PROJECTED':'LOCAL EVENT'}</span><h2>${esc(m.title)}</h2></div><button class="close" data-close aria-label="Close">×</button></div><p>${esc(fmt(event.at))} ${m.calendar.allDay?'/ ALL DAY':`/ ${m.calendar.duration} minutes / ${m.calendar.busy?'BUSY':'FREE'}`}</p><p class="muted">${esc(recurrenceLabel(m))}</p><p class="calendar-notes">${esc(m.calendar.notes||'No calendar notes.')}</p><p>${m.calendar.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join(' ')}</p><p class="muted">${esc(m.location)}</p>${event.projected?'<p class="fine-print">This is a projected date. Edit the current quest to change future dates; the next actual occurrence is created on completion.</p>':''}<div class="modal-actions"><button class="secondary" data-open-quest>Edit ${event.projected?'current quest / series':'quest'}</button>${!event.projected&&m.status==='active'?'<button class="primary" data-event-complete>Complete quest</button>':''}</div>`;modal.querySelector('[data-close]').onclick=()=>modal.close();modal.querySelector('[data-open-quest]').onclick=()=>openEditor('mission',m.id);if(modal.querySelector('[data-event-complete]'))modal.querySelector('[data-event-complete]').onclick=()=>confirmCompletion(m.id);if(!modal.open)modal.showModal();}
async function importCalendarFile(e){try{const file=e.target.files[0];if(!file)return;if(file.size>4000000)throw Error('Calendar file limit: 4 MB.');const text=await file.text();let incoming,warnings=[];if(file.name.toLowerCase().endsWith('.json')||text.trim().startsWith('{')){const data=JSON.parse(text);if(data.format!=='daemon-calendar'||data.version!==1||!Array.isArray(data.quests)||data.quests.length>2000)throw Error('Choose Daemon Calendar JSON, or an .ics file.');incoming=data.quests.map(m=>({...m,calendar:{...m.calendar,enabled:true,uid:m.calendar?.uid||`${m.id}@daemon-deck.local`}}));}else{const parsed=importICS(text);warnings=parsed.warnings;incoming=parsed.events.map(event=>({...missionDefaults(),...event,repeat:event.recurrence.frequency,createdAt:new Date(Math.min(Date.now(),new Date(event.dueAt)-86400000)).toISOString(),calendar:event.calendar}));}const known=new Set(state.missions.filter(m=>m.calendar.enabled).map(m=>m.calendar.uid||`${m.id}@daemon-deck.local`)),map=new Map(),quests=[];let skipped=0;for(const original of incoming){const id=original.calendar?.uid||`${original.title}:${original.dueAt}`;if(known.has(id)){skipped++;continue;}known.add(id);const sid=original.seriesId||id;if(!map.has(sid))map.set(sid,uid());quests.push({...original,id:uid(),seriesId:map.get(sid),parent:'',skills:[],repeatable:false,calendar:{...original.calendar,enabled:true,uid:id}});}validate({...state,missions:quests});const modal=$('#editor');modal.classList.remove('radar-dialog');modal.innerHTML=`<div class="modal-heading"><h2>Import calendar?</h2><button class="close" data-close aria-label="Close">×</button></div><p>${quests.length} quests to add / ${skipped} duplicates skipped.</p><p class="fine-print">Local quests and progress are preserved. Imported events become opted-in quests and can schedule future deadline alarms. Import does not award XP, credits, or change skills.</p>${warnings.length?`<p>${esc([...new Set(warnings)].join(' '))}</p>`:''}<div class="import-preview">${quests.slice(0,20).map(m=>`<div><span class="tag">${m.kind==='side'?'Side Quest':'Main'}</span><b>${esc(m.title)}</b><small>${esc(fmt(m.dueAt))}</small></div>`).join('')}</div><div class="modal-actions"><button class="secondary" data-close>Cancel</button><button class="primary" id="confirm-calendar-import" ${!quests.length?'disabled':''}>Import ${quests.length} quests</button></div>`;modal.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>modal.close());$('#confirm-calendar-import').onclick=()=>{if(mutate(()=>state.missions.push(...quests))){modal.close();render();toast('CALENDAR IMPORTED');}};modal.showModal();}catch(e){toast(e.message||'Calendar import failed.');}}
